from integration.target_pointcloud_localization import _transform

def main():
 ap=argparse.ArgumentParser();ap.add_argument('--root',type=pathlib.Path,required=True);a=ap.parse_args();root=a.root;frozen=json.loads((root/'frozen_sensor_decisions.json').read_text());aud=[]
 for row in frozen:
  frame=row['frame'];path=root/'frames'/str(frame);oracle=root/'oracle'/str(frame);truth=json.loads((oracle/'truth.json').read_text());d,lid,rgb,rad,ego,_=read(path);d['semantic_transform']=truth['semantic_transform'];raw=np.frombuffer(lid.raw_data,dtype=np.float32).reshape(-1,4);world=_transform(raw[:,:3],np.asarray(d['lidar_transform']));ids=sorted(set(row['formal_ids'])|set(row['aux_candidate_ids']));labels=audit_semantic(oracle,d,world,ids) if ids else {};target=truth['actor_ids']['T'];neighbor=truth['actor_ids']['N']
  def counts(idx,expected):
   points=[labels[i]['id'] for i in idx];return {'target':sum(x==expected for x in points),'other_vehicle':sum(x in {target,neighbor} and x!=expected for x in points),'other_known':sum(x is not None and x not in {target,neighbor} for x in points),'unmatched_semantic':sum(x is None for x in points)}
  ac=counts(row['aux_selected_ids'],target);fc=counts(row['formal_ids'],neighbor);eligible=counts(row['aux_candidate_ids'],target);n=len(row['aux_selected_ids']);dist=float(np.min(np.linalg.norm(_transform(world[row['aux_selected_ids']],np.linalg.inv(np.asarray(d['ego_transform'])))[:,:2],axis=1))) if n else None;gt=truth['gt_positions_all']['T']['nearest_box_distance_m']
  aud.append({'frame':frame,'formal_semantic_approx':fc,'aux_semantic_approx':ac,'eligible_target_approx':eligible['target'],'aux_precision_conservative':ac['target']/n if n else None,'aux_recall_conditional':ac['target']/eligible['target'] if eligible['target'] else None,'surface_distance_m':dist,'ground_truth_nearest_bbox_distance_m':gt,'surface_error_m':dist-gt if dist is not None else None,'different_vehicle_merged':ac['other_vehicle']>0 or fc['other_vehicle']>0,'ambiguous_semantic':ac['unmatched_semantic']+fc['unmatched_semantic']})
 (root/'offline_audit.json').write_text(json.dumps(aud,indent=2)+'\n');total_sel=sum(len(x['aux_selected_ids']) for x in frozen);total_target=sum(x['aux_semantic_approx']['target'] for x in aud);denom=sum(x['eligible_target_approx'] for x in aud);errors=[abs(x['surface_error_m']) for x in aud if x['surface_error_m'] is not None];timings=[x['processing_ms'] for x in frozen];states={c:dict(collections.Counter(s['state'] for r in frozen for s in r['states'] if s['channel']==c)) for c in ['formal','auxiliary']};track_ids={c:sorted(set(s['track_id'] for r in frozen for s in r['states'] if s['channel']==c)) for c in ['formal','auxiliary']};confirmed=[r['frame'] for r in frozen if all(any(s['channel']==c and s['state']=='CONFIRMED_TRACK' for s in r['states']) for c in ['formal','auxiliary'])];summary={'frames':len(frozen),'both_boxes_frames':sum(r['formal_box_matched'] and r['aux_box_matched'] for r in frozen),'separated_pairs_frames':sum(r['pair_separation_pass'] for r in frozen),'both_confirmed_frames':confirmed,'states':states,'track_ids':track_ids,'formal_unchanged_frames':sum(r['formal_result_unchanged'] for r in frozen),'unique_points_frames':sum(r['unique_points'] for r in frozen),'aux_cluster_frames':sum(bool(r['aux_selected_ids']) for r in frozen),'aux_selected_points':total_sel,'aux_target_approx':total_target,'aux_other_vehicle_approx':sum(x['aux_semantic_approx']['other_vehicle'] for x in aud),'aux_other_known':sum(x['aux_semantic_approx']['other_known'] for x in aud),'aux_unknown_semantic':sum(x['aux_semantic_approx']['unmatched_semantic'] for x in aud),'micro_precision_conservative':total_target/total_sel if total_sel else None,'conditional_recall_micro':total_target/denom if denom else None,'eligible_target_approx':denom,'different_vehicle_merged_frames':sum(x['different_vehicle_merged'] for x in aud),'surface_abs_error_p95_m':float(np.percentile(errors,95)) if errors else None,'surface_abs_error_max_m':max(errors) if errors else None,'elapsed_processing_p50_ms':float(np.percentile(timings,50)),'elapsed_processing_p95_ms':float(np.percentile(timings,95)),'processing_latency_note':'Offline replay includes ONNX inference, duplicate formal recalculation and audit instrumentation. Not a real-time or comparable baseline measurement.','semantic_note':'Approximate nearest semantic return within 8 cm, unmatched conservatively counted against precision. Recall is conditional on candidate eligible points, not full vehicle recall.','truth_role_note':'T/N are the reconstructed scene actors, used only after frozen decisions; cluster assignments are checked by semantic points, not ground-truth-derived tracker decisions.'}
 (root/'summary.json').write_text(json.dumps(summary,indent=2)+'\n');print(json.dumps(summary,indent=2))
